    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 overhead, uint256 scalar) public payable {
        require(overhead < 2**128 && scalar < 2**128);
        uint256 beforeOverhead;
        uint256 beforeScalar;
        beforeOverhead = c.l1FeeOverhead(); if (__ESBMC_reverted()) return;
        beforeScalar = c.l1FeeScalar(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.setL1BlockValues(1, 2, 3, bytes32(0), 4, bytes32(0), overhead, scalar); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted && c.l1FeeOverhead() == beforeOverhead && c.l1FeeScalar() == beforeScalar);
    }
    receive() external payable {}
}

