contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint256 overhead, uint256 scalar) internal {
        vm.assume(overhead < 2**128 && scalar < 2**128);
        uint256 beforeOverhead;
        uint256 beforeScalar;
        try c.l1FeeOverhead() returns (uint256 __r) { beforeOverhead = __r; } catch { return; }
        try c.l1FeeScalar() returns (uint256 __r) { beforeScalar = __r; } catch { return; }
        bool reverted;
        try c.setL1BlockValues(1, 2, 3, bytes32(0), 4, bytes32(0), overhead, scalar) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.l1FeeOverhead() == beforeOverhead && c.l1FeeScalar() == beforeScalar);
    }

    function testFuzz_run(uint256 overhead, uint256 scalar) public {
        _run(overhead, scalar);
    }

    receive() external payable {}
